      "path": "src/App.tsx",
      "language": "typescript",
      "content": "import { useMemo, useState } from "react";
import { planDinners } from "./planner";

export function App() {
  const [budget, setBudget] = useState(120);
  const [familySize, setFamilySize] = useState(4);

  const plan = useMemo(() => planDinners({ budget, familySize }), [budget, familySize]);

  return (
    <main className="container">
      <header>
        <h1>Dinner Planner</h1>
        <p>Plan a week of dinners on a budget.</p>
      </header>

      <section className="card controls">
        <label>
          Budget
          <input
            type="number"
            min={1}
            value={budget}
            onChange={(e) => setBudget(Number(e.target.value))}
          />
        </label>

        <label>
          Family size
          <input
            type="number"
            min={1}
            value={familySize}
            onChange={(e) => setFamilySize(Number(e.target.value))}
          />
        </label>
      </section>

      <section className="grid">
        <div className="card">
          <h2>Days</h2>
          <ul>
            {plan.days.map((day) => (
              <li key={day.day}>
                <strong>{day.day}:</strong> {day.meal} (${day.cost.toFixed(2)})
              </li>
            ))}
          </ul>
        </div>

        <div className="card">
          <h2>Shopping List</h2>
          <ul>
            {plan.shoppingList.map((item) => (
              <li key={item}>{item}</li>
            ))}
          </ul>
        </div>
      </section>

      <section className="card summary">
        <p><strong>Total cost:</strong> ${plan.totalCost.toFixed(2)}</p>
        <p><strong>Within budget:</strong> {plan.totalCost <= budget ? "Yes" : "No"}</p>
        <p><strong>Distinct meals:</strong> {new Set(plan.days.map((d) => d.meal)).size}</p>
      </section>
    </main>
  );
}
"
