    {
      "path": "src/planner.ts",
      "language": "typescript",
      "content": "export type PlannerInput = {
  budget: number;
  familySize: number;
};

export type DayPlan = {
  day: string;
  meal: string;
  cost: number;
};

export type PlannerOutput = {
  days: DayPlan[];
  shoppingList: string[];
  totalCost: number;
};

const baseMeals = [
  { meal: "Chicken Stir-Fry", baseCost: 14, ingredients: ["chicken", "rice", "broccoli", "soy sauce"] },
  { meal: "Spaghetti Marinara", baseCost: 10, ingredients: ["spaghetti", "tomato sauce", "garlic", "parmesan"] },
  { meal: "Bean Tacos", baseCost: 9, ingredients: ["tortillas", "beans", "lettuce", "cheese"] },
  { meal: "Veggie Curry", baseCost: 12, ingredients: ["coconut milk", "curry paste", "potatoes", "carrots"] },
  { meal: "Baked Salmon", baseCost: 18, ingredients: ["salmon", "lemon", "green beans", "potatoes"] },
  { meal: "Turkey Chili", baseCost: 13, ingredients: ["ground turkey", "beans", "tomatoes", "onion"] },
  { meal: "Fried Rice", baseCost: 11, ingredients: ["rice", "eggs", "peas", "carrots"] }
];

const dayNames = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

export function planDinners(input: PlannerInput): PlannerOutput {
  const multiplier = Math.max(1, input.familySize / 4);
  const days = dayNames.map((day, index) => {
    const template = baseMeals[index];
    return {
      day,
      meal: template.meal,
      cost: Number((template.baseCost * multiplier).toFixed(2))
    };
  });

  const totalCost = Number(days.reduce((sum, day) => sum + day.cost, 0).toFixed(2));
  const shoppingList = Array.from(new Set(baseMeals.flatMap((meal) => meal.ingredients)));

  // TODO(code-dj): "Success criteria" may require a smarter optimizer when scaled family costs exceed budget.
  // TODO(code-dj): "I/O contract" may require exporting raw days[] and shoppingList[] to another boundary.

  return {
    days,
    shoppingList,
    totalCost
  };
}
